1	import { Router, type Request, type Response } from "express";
2	import multer from "multer";
3	import createDOMPurify from "dompurify";
4	import { JSDOM } from "jsdom";
5	import type { Db } from "@paperclipai/db";
6	import { createAssetImageMetadataSchema } from "@paperclipai/shared";
7	import type { StorageService } from "../storage/types.js";
8	import { assetService, logActivity } from "../services/index.js";
9	import { isAllowedContentType, MAX_ATTACHMENT_BYTES } from "../attachment-types.js";
10	import { assertCompanyAccess, getActorInfo } from "./authz.js";
11	const SVG_CONTENT_TYPE = "image/svg+xml";
12	const ALLOWED_COMPANY_LOGO_CONTENT_TYPES = new Set([
13	  "image/png",
14	  "image/jpeg",
15	  "image/jpg",
16	  "image/webp",
17	  "image/gif",
18	  SVG_CONTENT_TYPE,
19	]);
