85	export function assetRoutes(db: Db, storage: StorageService) {
86	  const router = Router();
87	  const svc = assetService(db);
88	  const assetUpload = multer({
89	    storage: multer.memoryStorage(),
90	    limits: { fileSize: MAX_ATTACHMENT_BYTES, files: 1 },
91	  });
92	  const companyLogoUpload = multer({
93	    storage: multer.memoryStorage(),
94	    limits: { fileSize: MAX_ATTACHMENT_BYTES, files: 1 },
95	  });
96	
97	  async function runSingleFileUpload(
98	    upload: ReturnType<typeof multer>,
99	    req: Request,
100	    res: Response,
101	  ) {
102	    await new Promise<void>((resolve, reject) => {
103	      upload.single("file")(req, res, (err: unknown) => {
104	        if (err) reject(err);
105	        else resolve();
106	      });
107	    });
108	  }
109	
110	  router.post("/companies/:companyId/assets/images", async (req, res) => {
111	    const companyId = req.params.companyId as string;
112	    assertCompanyAccess(req, companyId);
113	
114	    try {
115	      await runSingleFileUpload(assetUpload, req, res);
116	    } catch (err) {
117	      if (err instanceof multer.MulterError) {
118	        if (err.code === "LIMIT_FILE_SIZE") {
119	          res.status(422).json({ error: `File exceeds ${MAX_ATTACHMENT_BYTES} bytes` });
120	          return;
121	        }
122	        res.status(400).json({ error: err.message });
123	        return;
124	      }
125	      throw err;
126	    }
127	
128	    const file = (req as Request & { file?: { mimetype: string; buffer: Buffer; originalname: string } }).file;
129	    if (!file) {
130	      res.status(400).json({ error: "Missing file field 'file'" });
131	      return;
132	    }
133	
134	    const parsedMeta = createAssetImageMetadataSchema.safeParse(req.body ?? {});
135	    if (!parsedMeta.success) {
136	      res.status(400).json({ error: "Invalid image metadata", details: parsedMeta.error.issues });
137	      return;
138	    }
139	
140	    const namespaceSuffix = parsedMeta.data.namespace ?? "general";
141	    const contentType = (file.mimetype || "").toLowerCase();
142	    if (contentType !== SVG_CONTENT_TYPE && !isAllowedContentType(contentType)) {
143	      res.status(422).json({ error: `Unsupported file type: ${contentType || "unknown"}` });
144	      return;
145	    }
146	    let fileBody = file.buffer;
147	    if (contentType === SVG_CONTENT_TYPE) {
148	      const sanitized = sanitizeSvgBuffer(file.buffer);
149	      if (!sanitized || sanitized.length <= 0) {
150	        res.status(422).json({ error: "SVG could not be sanitized" });
151	        return;
152	      }
153	      fileBody = sanitized;
154	    }
155	    if (fileBody.length <= 0) {
156	      res.status(422).json({ error: "Image is empty" });
157	      return;
158	    }
159	
160	    const actor = getActorInfo(req);
161	    const stored = await storage.putFile({
162	      companyId,
163	      namespace: `assets/${namespaceSuffix}`,
164	      originalFilename: file.originalname || null,
165	      contentType,
166	      body: fileBody,
167	    });
168	
169	    const asset = await svc.create(companyId, {
170	      provider: stored.provider,
171	      objectKey: stored.objectKey,
172	      contentType: stored.contentType,
173	      byteSize: stored.byteSize,
174	      sha256: stored.sha256,
175	      originalFilename: stored.originalFilename,
176	      createdByAgentId: actor.agentId,
177	      createdByUserId: actor.actorType === "user" ? actor.actorId : null,
178	    });
179	
180	    await logActivity(db, {
181	      companyId,
182	      actorType: actor.actorType,
183	      actorId: actor.actorId,
184	      agentId: actor.agentId,
185	      runId: actor.runId,
186	      action: "asset.created",
187	      entityType: "asset",
188	      entityId: asset.id,
189	      details: {
190	        originalFilename: asset.originalFilename,
191	        contentType: asset.contentType,
192	        byteSize: asset.byteSize,
193	      },
194	    });
195	
196	    res.status(201).json({
197	      assetId: asset.id,
198	      companyId: asset.companyId,
199	      provider: asset.provider,
200	      objectKey: asset.objectKey,
201	      contentType: asset.contentType,
202	      byteSize: asset.byteSize,
203	      sha256: asset.sha256,
204	      originalFilename: asset.originalFilename,
205	      createdByAgentId: asset.createdByAgentId,
206	      createdByUserId: asset.createdByUserId,
207	      createdAt: asset.createdAt,
208	      updatedAt: asset.updatedAt,
209	      contentPath: `/api/assets/${asset.id}/content`,
210	    });
211	  });
212	
213	  router.post("/companies/:companyId/logo", async (req, res) => {
214	    const companyId = req.params.companyId as string;
215	    assertCompanyAccess(req, companyId);
216	
217	    try {
218	      await runSingleFileUpload(companyLogoUpload, req, res);
219	    } catch (err) {
220	      if (err instanceof multer.MulterError) {
221	        if (err.code === "LIMIT_FILE_SIZE") {
222	          res.status(422).json({ error: `Image exceeds ${MAX_ATTACHMENT_BYTES} bytes` });
223	          return;
224	        }
225	        res.status(400).json({ error: err.message });
226	        return;
227	      }
228	      throw err;
229	    }
230	
231	    const file = (req as Request & { file?: { mimetype: string; buffer: Buffer; originalname: string } }).file;
232	    if (!file) {
233	      res.status(400).json({ error: "Missing file field 'file'" });
234	      return;
235	    }
236	
237	    const contentType = (file.mimetype || "").toLowerCase();
238	    if (!ALLOWED_COMPANY_LOGO_CONTENT_TYPES.has(contentType)) {
239	      res.status(422).json({ error: `Unsupported image type: ${contentType || "unknown"}` });
240	      return;
241	    }
242	
243	    let fileBody = file.buffer;
244	    if (contentType === SVG_CONTENT_TYPE) {
245	      const sanitized = sanitizeSvgBuffer(file.buffer);
246	      if (!sanitized || sanitized.length <= 0) {
247	        res.status(422).json({ error: "SVG could not be sanitized" });
248	        return;
249	      }
250	      fileBody = sanitized;
251	    }
252	
253	    if (fileBody.length <= 0) {
254	      res.status(422).json({ error: "Image is empty" });
255	      return;
256	    }
257	
258	    const actor = getActorInfo(req);
259	    const stored = await storage.putFile({
260	      companyId,
261	      namespace: "assets/companies",
262	      originalFilename: file.originalname || null,
263	      contentType,
264	      body: fileBody,
265	    });
266	
267	    const asset = await svc.create(companyId, {
268	      provider: stored.provider,
269	      objectKey: stored.objectKey,
270	      contentType: stored.contentType,
271	      byteSize: stored.byteSize,
272	      sha256: stored.sha256,
273	      originalFilename: stored.originalFilename,
274	      createdByAgentId: actor.agentId,
275	      createdByUserId: actor.actorType === "user" ? actor.actorId : null,
276	    });
277	
278	    await logActivity(db, {
279	      companyId,
280	      actorType: actor.actorType,
281	      actorId: actor.actorId,
282	      agentId: actor.agentId,
283	      runId: actor.runId,
284	      action: "asset.created",
285	      entityType: "asset",
286	      entityId: asset.id,
287	      details: {
288	        originalFilename: asset.originalFilename,
289	        contentType: asset.contentType,
290	        byteSize: asset.byteSize,
291	        namespace: "assets/companies",
292	      },
293	    });
294	
295	    res.status(201).json({
296	      assetId: asset.id,
297	      companyId: asset.companyId,
298	      provider: asset.provider,
299	      objectKey: asset.objectKey,
300	      contentType: asset.contentType,
301	      byteSize: asset.byteSize,
302	      sha256: asset.sha256,
303	      originalFilename: asset.originalFilename,
304	      createdByAgentId: asset.createdByAgentId,
305	      createdByUserId: asset.createdByUserId,
306	      createdAt: asset.createdAt,
307	      updatedAt: asset.updatedAt,
308	      contentPath: `/api/assets/${asset.id}/content`,
309	    });
310	  });
311	
312	  router.get("/assets/:assetId/content", async (req, res, next) => {
313	    const assetId = req.params.assetId as string;
314	    const asset = await svc.getById(assetId);
315	    if (!asset) {
316	      res.status(404).json({ error: "Asset not found" });
317	      return;
318	    }
319	    assertCompanyAccess(req, asset.companyId);
320	
321	    const object = await storage.getObject(asset.companyId, asset.objectKey);
322	    const responseContentType = asset.contentType || object.contentType || "application/octet-stream";
323	    res.setHeader("Content-Type", responseContentType);
324	    res.setHeader("Content-Length", String(asset.byteSize || object.contentLength || 0));
325	    res.setHeader("Cache-Control", "private, max-age=60");
326	    res.setHeader("X-Content-Type-Options", "nosniff");
327	    if (responseContentType === SVG_CONTENT_TYPE) {
328	      res.setHeader("Content-Security-Policy", "sandbox; default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'");
329	    }
330	    const filename = asset.originalFilename ?? "asset";
331	    res.setHeader("Content-Disposition", `inline; filename=\"${filename.replaceAll("\"", "")}\"`);
332	
333	    object.stream.on("error", (err) => {
334	      next(err);
335	    });
336	    object.stream.pipe(res);
337	  });
338	
339	  return router;
340	}
